Lemma dbp_pro : forall (Q : machine_state -> Prop) (m : mem) (lo : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  stk bsegs m lo (bv_unsigned sp) -> lo + 208 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp mod 16 = 0 -> mem_inv bsegs m ->
  (forall (m1 : mem) (spa : Z) (j88 : list byte) (gap : list cell),
     munch [(lo, bv_unsigned sp)]%Z m m1 -> wmono bsegs m m1 -> mem_inv bsegs m1 ->
     (spa = bv_unsigned sp + -192 \/ spa = bv_unsigned sp + -208) -> spa mod 32 = 0 ->
     stk bsegs m1 lo spa ->
     rw_cells bsegs m1 spa [CB 88 j88] ->
     rw_cells bsegs m1 (spa + 88) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 88) ->
     rw_cells bsegs m1 (bv_unsigned sp + -104) (prep_saves s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
     evt bsegs Q (MS (mkR ra (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                     F (Z_to_bv 64 P_A_DBP_B) fc None m1 (seg_rom bsegs))) ->
  evt bsegs Q (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                 F (Z_to_bv 64 P_A_MB_DYN_PREPARE) fc None m (seg_rom bsegs)).
