Definition dbp_locals1 (a4w : word) (E ff : Z) (j0 j32 j64 : list byte) : list cell :=
  [CB 24 j0; C8 a4w; CB 24 j32; C8 (wz ff); CB 24 j64].   (* [comment removed for export] *)

