Definition dbp_ffa (spa : Z) : list cell :=
  [C8 (Z_to_bv 64 0x41b58ab3); C8 (Z_to_bv 64 0x15c0e); C8 (Z_to_bv 64 0xc0454); C8 (Z_to_bv 64 spa)].

(* [comment removed for export] *)
Definition dbp_sh1 : list cell :=
  [C1 (b8 (-15 mod 256)); C1 (b8 (-15 mod 256)); C1 (b8 (-15 mod 256)); C1 (b8 (-15 mod 256));
   C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0);
