(* [comment removed for export] *)
Definition dbp_frontW (lo spa ff fp R : Z) : list (Z * Z) :=
  [(lo, spa + 88); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16); (R, R + 48)]%Z.

(* [comment removed for export] *)
Lemma dbp_res_acc : forall m ff (c0 c1 c2 c3 c9 c10 c11 c12 c13 c14 c15 : byte),
  0 <= ff -> ff mod 8 = 0 -> ff + 128 <= AAPP_HI ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880)
    [C1 c0; C1 c1; C1 c2; C1 c3; C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 c9; C1 c10; C1 c11; C1 c12; C1 c13; C1 c14; C1 c15] ->
